"""API-Definition EduKSX-Flow."""

O = "/api/v1/org"


def R(tabelle, schema, op, op_mehrzahl, einzahl, mehrzahl, **kw):
    return {"tabelle": tabelle, "schema": schema, "op": op, "op_mehrzahl": op_mehrzahl, "einzahl": einzahl, "mehrzahl": mehrzahl,
            "pfad": f"{O}/{tabelle.replace('_', '-')}", **kw}


STATUS_SCHRITT = "enum:waiting=wartet;ready=bereit;scheduled=geplant;running=läuft;done=erledigt;skipped=übersprungen;failed=Fehler;cancelled=abgebrochen"
